function dpDeriv(s, g, l1, l2, m1, m2){
  var t1 = s[0], w1 = s[1], t2 = s[2], w2 = s[3];
  var d = t1 - t2, cd = Math.cos(d), sd = Math.sin(d);
  var den = 2*m1 + m2 - m2*Math.cos(2*d);
  var dw1 = (-g*(2*m1+m2)*Math.sin(t1) - m2*g*Math.sin(t1-2*t2) - 2*sd*m2*(w2*w2*l2 + w1*w1*l1*cd)) / (l1*den);
  var dw2 = (2*sd*(w1*w1*l1*(m1+m2) + g*(m1+m2)*Math.cos(t1) + w2*w2*l2*m2*cd)) / (l2*den);
  return [w1, dw1, w2, dw2];
}
function dpRk4(s, dt, g, l1, l2, m1, m2){
  function add(a, b, f){ return [a[0]+b[0]*f, a[1]+b[1]*f, a[2]+b[2]*f, a[3]+b[3]*f]; }
  var k1 = dpDeriv(s, g, l1, l2, m1, m2);
  var k2 = dpDeriv(add(s, k1, dt/2), g, l1, l2, m1, m2);
  var k3 = dpDeriv(add(s, k2, dt/2), g, l1, l2, m1, m2);
  var k4 = dpDeriv(add(s, k3, dt), g, l1, l2, m1, m2);
  return [
    s[0] + dt/6*(k1[0] + 2*k2[0] + 2*k3[0] + k4[0]),
    s[1] + dt/6*(k1[1] + 2*k2[1] + 2*k3[1] + k4[1]),
    s[2] + dt/6*(k1[2] + 2*k2[2] + 2*k3[2] + k4[2]),
    s[3] + dt/6*(k1[3] + 2*k2[3] + 2*k3[3] + k4[3])
  ];
}
function dpEnergy(s, g, l1, l2, m1, m2){
  var t1 = s[0], w1 = s[1], t2 = s[2], w2 = s[3];
  var v1 = l1*w1, ke = 0.5*m1*v1*v1;
  var vx2 = l1*w1*Math.cos(t1) + l2*w2*Math.cos(t2);
  var vy2 = l1*w1*Math.sin(t1) + l2*w2*Math.sin(t2);
  ke += 0.5*m2*(vx2*vx2 + vy2*vy2);
  var y1 = -l1*Math.cos(t1), y2 = y1 - l2*Math.cos(t2);
  return ke + m1*g*y1 + m2*g*y2;
}
function dpPos(s, l1, l2){
  var x1 = l1*Math.sin(s[0]), y1 = l1*Math.cos(s[0]);
  return { x1: x1, y1: y1, x2: x1 + l2*Math.sin(s[2]), y2: y1 + l2*Math.cos(s[2]) };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dpDeriv:dpDeriv, dpRk4:dpRk4, dpEnergy:dpEnergy, dpPos:dpPos };
}
if (typeof window !== 'undefined') {
  window.PendulumForgePure = { dpDeriv:dpDeriv, dpRk4:dpRk4, dpEnergy:dpEnergy, dpPos:dpPos };
}
